%[text] ## Exo 1
clear;
Table = readtable('yield_curves.csv');
years = linspace(0.25,30,120);
dates_juin = [datetime(1995,6,1), datetime(2000,6,1), datetime(2005,6,1), datetime(2010,6,1), datetime(2015,6,1), datetime(2018,6,1), datetime(2020,6,1), datetime(2023,6,1)];
rows = ismember(Table.Date, dates_juin);
Table_juin = Table(rows, 1:121);
for i = 1:width(Table_juin)
    if iscell(Table_juin.(i))
        Table_juin.(i) = str2double(Table_juin.(i));
    end
end

Table_juin %[output:6f55f4a6]
         

function Ytm = MyNelsonSiegleFunction(x,Maturity)
    Ytm = nan(numel(Maturity),1);
    
    b0 = x(1);
    b1 = x(2);
    b2 = x(3);
    tau = x(4);
    for ind=1:numel(Maturity)
        m = Maturity(ind);
        Ytm(ind) = b0 ...
            + (b1).*(1-exp(-m.*tau))./(m.*tau) + ...
            + b2.*((1-exp(-m.*tau))./(m.*tau) - exp(-m.*tau));
    end
end
x0_set_value = { [0.02, -0.01, 0.02, 0.5], ...
                 [0.03, -0.02, 0.03, 0.3], ...
                 [0.01, 0.01, -0.01, 0.7], ...
                 [0.02, 0.1, -0.1, 0.2], ...
                 [0.03, -0.05, 0.05, 2], ...
                 [0.01, 0.1, 0.1, 0.05], ...
               };
x0_set_name = { "typical-1", ...
                 "typical-2", ...
                 "typical-3", ...
                 "extreme curvature", ...
                 "steep decay", ...
                 "wide range", ...
               };
options = optimoptions('lsqnonlin','Display','off');

% 1 to 8 est la date
for i = 1:8 %[output:group:8b7dd2ca]

    ZCrates = Table_juin{i,2:121};
    PriceErrorVectorFunction = @(x) (MyNelsonSiegleFunction(x,years) - ZCrates.');
    best_SSE = Inf;
    best_init = "";
    best_Params = [0,0,0,0];
    
    
    % boucle pour choisir best x0
    for k = 1:length(x0_set_value)
        x0 = x0_set_value{k};
    
        [params, resnorm, residual] = lsqnonlin(PriceErrorVectorFunction,x0,[],[],options);
        
        w = sqrt(years); 
        Wres = residual.';
        WSSE = sum(Wres.^2);
        if abs(WSSE-best_SSE)<eps(resnorm)*4
            best_init = best_init + " and " + x0_set_name{k};
        elseif WSSE < best_SSE
            best_SSE = WSSE;
            best_Params = params;
            best_init = x0_set_name{k};
            bestX0 = x0;
        end
    end
    
    
    best_Params %[output:1a11c379] %[output:5c34a1a6] %[output:20d27eaf] %[output:4eda0e12] %[output:500ffb86] %[output:4a0ca5ce] %[output:5db53c61] %[output:30fe7040]
    fig = figure('Position', [100 100 1200 700]);     %[output:845900a4] %[output:0fb075a7] %[output:8d00a1d6] %[output:94b71a91] %[output:6faba5d0] %[output:6e2dd119] %[output:28781523] %[output:5575fb47]
    ax = gca; %[output:845900a4] %[output:0fb075a7] %[output:8d00a1d6] %[output:94b71a91] %[output:6faba5d0] %[output:6e2dd119] %[output:28781523] %[output:5575fb47]
    ax.Position = [0.1 0.2 0.8 0.7]; 
    
    yfit = MyNelsonSiegleFunction(best_Params,years);
    hold on;
    plot(years, ZCrates, 'LineWidth', 1.5, 'Color', 'red');
    plot(years, yfit, 'LineWidth', 1.5, 'Color', 'blue');
    hold off;
    
    
    annotation('textbox',[.67 0 .1 .1], ...
        'String',sprintf('Weighted SSE = %.9f', best_SSE),'EdgeColor','none')
    
    txt = sprintf('Weighted SSE = %.9f', best_SSE);
    xpos = 20.5;   % 5% from left
    ypos = -1; % near top
    
    text(xpos, ypos, txt, 'FontSize', 12, 'BackgroundColor', 'white');
    lgd = legend(ax, ["Données réelles","NelsonSiegle (x0 = "+best_init+")"],NumColumns=1);
    lgd.Color = 'w';
    lgd.TextColor = 'k';
    lgd.Box = 'off';
    
    % Position legend manually (normalized figure coordinates)
    lgd.Units = 'normalized';
    lgd.Position = [0.25 0.03 0.5 0.05];  % [left bottom width height]
    
    xlabel('Maturité (0.25 à 30 ans, step=0.25)');
    ylabel('Rendement (en %, 0.05 = 5%)');
    t = title("Comparaison entre le fit du modèle Nelson-Siegle et les données réelles (Date = "+string(dates_juin(i))+")");
    t.Units = 'normalized';
    t.Position(2) = t.Position(2) + 0.02;
    grid on;
end %[output:group:8b7dd2ca]
