%%

% pi_foreign = log(cpi_table(2:251,:))-log(cpi_table(1:250,:));
% pi_usa = log(cpi_usa(2:251))-log(cpi_usa(1:250));


pi_foreign = log(cpi_table(2:251,:))-log(cpi_table(1:250,:));
pi_usa = log(cpi_usa(2:251))-log(cpi_usa(1:250));
pvalue_tol = 1;

eta_t_table = [];
prime_table = [];
% 1 to 5 est le pays dans l'ordre Canada, Euro, Japan, Switzerland, UK
for i = 1:5 %[output:group:37774161]
    disp("Calculation de prime de risque pour "+string(pays(i))) %[output:9a9e2cc8] %[output:038d76b4] %[output:55197d18] %[output:83060001] %[output:10693e5b]

    % regression 1
    y = pi_foreign-pi_usa;
    X = ones(length(y),1);
    mdl_pi = fitlm(X, y(:,i), 'Intercept', false) %[output:08bdde64] %[output:12190287] %[output:38111187] %[output:940faa01] %[output:87bff784]
    if mdl_pi.Coefficients{1,"pValue"} >pvalue_tol
        mu_pi = 0;
    else
        mu_pi = mdl_pi.Coefficients{1,"Estimate"};
    end
    
    % regression 2
    y = interet_table(2:251,:)-interet_usa(2:251);
    X = interet_table(1:250,:)-interet_usa(1:250);
    mdl_interet = fitlm(X(:,i), y(:,i)) %[output:18f79de8] %[output:614f3ac4] %[output:2fd4abe6] %[output:82a30893] %[output:3b67c5d4]
    if mdl_interet.Coefficients{2,"pValue"} >pvalue_tol
        rho_i = 0;
    else
        rho_i = mdl_interet.Coefficients{2,"Estimate"};
    end
    
    if mdl_interet.Coefficients{1,"pValue"} >pvalue_tol
        mu_i = 0;
    else
        mu_i = mdl_interet.Coefficients{1,"Estimate"}/(1-rho_i);
    end
    
    % regression 3
    r_t = log(taux_change_table(2:251,:))-log(taux_change_table(1:250,:))+interet_table(1:250,:)-interet_usa(1:250);
    q_t = log(taux_change_table(1:250,:))+log(cpi_table(1:250,:))-log(cpi_usa(1:250));
    diff_i = interet_table(1:250,:)-interet_usa(1:250);
    X = [diff_i(:,i),q_t(:,i)];
    mdl_rt = fitlm(X, r_t(:,i)) %[output:668870c5] %[output:63ed5af5] %[output:11791466] %[output:7c7ff704] %[output:71688d12]
    
    if mdl_rt.Coefficients{3,"pValue"} >pvalue_tol
        rho_eta = 1;
    else
        rho_eta = 1+ mdl_rt.Coefficients{3,"Estimate"};
    end
    
    if mdl_rt.Coefficients{2,"pValue"} >pvalue_tol
        b = 1;
    else
        b = 1 - mdl_rt.Coefficients{2,"Estimate"};
    end
    beta = b*(1-rho_i)/(rho_eta-rho_i);
    
    
    
    % calcul de eta + prime
    eta_t = (1-rho_eta)*(beta.*(diff_i(:,i)-mu_i)/(1-rho_i)-(q_t(:,i)-mean(q_t(:,i),"omitnan")));
    alpha = beta*mu_i-mu_pi;
    prime = alpha + (1-beta).*diff_i(:,i)+eta_t;
    eta_t_table = [eta_t_table,eta_t];
    prime_table = [prime_table,prime];
    
    % display parameters
    mu_pi %[output:3d5dc373] %[output:0d3d542b] %[output:0d0838ee] %[output:2728e131] %[output:93f12bb4]
    mu_i %[output:4b38a089] %[output:07fb389b] %[output:2b6fa369] %[output:9c6b88cd] %[output:38181103]
    rho_i %[output:90a00274] %[output:77977496] %[output:7295ea09] %[output:9dc822db] %[output:63ef68fb]
    rho_eta %[output:469a69d7] %[output:458b13aa] %[output:193bbba5] %[output:2ac66621] %[output:1f175eaa]
    alpha %[output:9d14476b] %[output:3b339bb8] %[output:3e99d120] %[output:0b708276] %[output:5e94029d]
    beta %[output:9a67aae0] %[output:6614d4a6] %[output:447d5734] %[output:9a2b23b1] %[output:9befd48e]
    disp('--------------------------------------------------------------------------------------') %[output:456934b1] %[output:0ba4f912] %[output:1a5d631b] %[output:126a886b] %[output:27f5c461]
end %[output:group:37774161]


